using System;
using System.Runtime.InteropServices;

public class ClipboardUtil {
    [DllImport("user32.dll")]
    public static extern IntPtr GetOpenClipboardWindow();

    [DllImport("user32.dll", SetLastError = true)]
    public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
}
"@

$hwnd = [ClipboardUtil]::GetOpenClipboardWindow()
if ($hwnd -ne [IntPtr]::Zero) {
    $processId = 0
    [ClipboardUtil]::GetWindowThreadProcessId($hwnd, [ref]$processId)
    $proc = Get-Process -Id $processId -ErrorAction SilentlyContinue
    if ($proc) {
        Write-Output "Clipboard is locked by: $($proc.Name) (PID: $processId) / Window Title: $($proc.MainWindowTitle)"
    } else {
        Write-Output "Clipboard is locked by HWND: $hwnd (PID: $processId, but process not found)"
    }
} else {
    Write-Output "Clipboard is not currently locked."
}
"

"$procNames = @("excel", "chrome", "msedge", "whale", "ditto", "remoting_host", "teamviewer", "anydesk", "iexplore", "snippingtool", "hwp", "hancom")
foreach ($name in $procNames) {
    $proc = Get-Process -Name $name -ErrorAction SilentlyContinue
    if ($proc) {
        Write-Output "Found process: $name (PIDs: $($proc.Id -join ', '))"
    }
}
"

